import json, re
_DROP = re.compile('образец цвета|инструкция по уходу|уход за вещами|условия хранения|о драгоценном металле|примечание|дополнительная информация|гарантийн|срок службы|валюта|признак 18|информация о размерах|описание|вид выпуска товара|страна бренда|целевая аудитория$')
_PRIO = ['артикул', 'артикул производителя', 'партномер (артикул производителя)', 'партномер', 'oem-номер', 'оем номер', 'модель', 'код товара', 'альтернативные артикулы товара', 'тип', 'бренд', 'бренд в одежде и обуви', 'цвет товара', 'цвет', 'название цвета', 'объем, мл', 'объем', 'объем товара', 'объём', 'количество в упаковке', 'количество в упаковке, шт', 'единиц в одном товаре', 'количество предметов в упаковке', 'количество, штук', 'комплектация', 'состав', 'в наборе', 'вес товара, г', 'вес, кг', 'вес', 'материал', 'материал изделия', 'размеры, мм', 'размеры (вxшxг)', 'высота, см', 'ширина, см', 'глубина, см', 'длина, см', 'высота предмета', 'ширина предмета', 'глубина предмета', 'диаметр, мм']

def card(row, max_attr=28, val_max=120, attr_chars=1200, name_chars=220):
    try:
        d = json.loads(row['attributes'])
    except Exception:
        d = {}
    d = {k: v for (k, v) in d.items() if str(v).strip() and (not _DROP.search(k))}
    keys = [k for k in _PRIO if k in d] + [k for k in d if k not in _PRIO]
    s = '; '.join((f'{k}: {str(d[k])[:val_max]}' for k in keys[:max_attr]))
    return f"Название: {str(row['name'])[:name_chars]}\nАтрибуты: {s[:attr_chars]}"
