USER_TMPL = 'Категория: {cat}\n\nКарточка A\n{a}\n\nКарточка B\n{b}\n\nОдин и тот же товар? Ответь одним словом (да/нет):'

def build_messages(a, b, cat, variant='medium'):
    u = USER_TMPL.format(cat=cat, a=card(a), b=card(b))
    if variant == 'short':
        return [{'role': 'system', 'content': SYS_SHORT}, {'role': 'user', 'content': u}]
    if variant == 'medium':
        return [{'role': 'system', 'content': SYS_MEDIUM}, {'role': 'user', 'content': u}]
    if variant == 'fewshot':
        msgs = [{'role': 'system', 'content': SYS_FEWSHOT}]
        for (q, ans) in FEWSHOT:
            msgs.append({'role': 'user', 'content': q + '\n\nОдин и тот же товар? Ответь одним словом (да/нет):'})
            msgs.append({'role': 'assistant', 'content': ans})
        msgs.append({'role': 'user', 'content': u})
        return msgs
    raise ValueError(variant)

def yes_no_ids(tok):
    yes = {tok.encode(w, add_special_tokens=False)[0] for w in ['да', 'Да', 'ДА', ' да']}
    no = {tok.encode(w, add_special_tokens=False)[0] for w in ['нет', 'Нет', 'НЕТ', ' нет']}
    return (sorted(yes), sorted(no))

def score_from_logits(logits, yes_ids, no_ids):
    import torch
    lp = torch.log_softmax(logits, dim=-1)
    y = torch.logsumexp(lp[:, yes_ids], dim=-1)
    n = torch.logsumexp(lp[:, no_ids], dim=-1)
    return (y - n).cpu().numpy()
